select v.id, v.name, 'UNKNOWN', v.programs, v.notes, true, false,
       public.derive_lender_loan_types(v.programs, 'UNKNOWN', v.notes, '{}'::text[], '{}'::text[]), 'migration:20261105150000_int_lender_contacts_research'
